def load() -> pd.DataFrame:
    import pandas as pd, glob, os
    paths = sorted(glob.glob('data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*.csv'))
    rows = []
    for p in paths[:3] + (paths[-3:] if len(paths) > 3 else []):
        try:
            df = pd.read_csv(p)
        except Exception:
            df = pd.read_csv(p, encoding='latin1')
        rows.append({
            'file': os.path.basename(p),
            'nrows': len(df),
            'ncols': df.shape[1],
            'columns': ','.join(map(str, df.columns[:20]))
        })
    return pd.DataFrame(rows)

